import {RouteStrip} from './route-strip.js';
const $=s=>document.querySelector(s),L=window.L;
let prefs={mode:'follow',zoom:15,source:'live',band:0};try{prefs={...prefs,...JSON.parse(localStorage.getItem('rheinrail-navi')||'{}')};}catch{}
if(!['follow','free','preview'].includes(prefs.mode))prefs.mode='follow';if(!['live','demo'].includes(prefs.source))prefs.source='live';
const save=()=>{try{localStorage.setItem('rheinrail-navi',JSON.stringify(prefs));}catch{}};
const map=L.map('map',{zoomControl:false,attributionControl:true,minZoom:3,maxZoom:19,touchZoom:true,scrollWheelZoom:true,zoomSnap:.5}).setView([51,10],Math.max(3,Math.min(19,prefs.zoom)));
L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> · reale Karte'}).addTo(map).on('tileerror',()=>notice('Kartenkacheln nicht erreichbar. Internetverbindung prüfen.'));
const trace=L.polyline([],{color:'#50d6c1',weight:4,opacity:.85}).addTo(map),stationsLayer=L.layerGroup().addTo(map);
let marker,data,lastVehicle,seenPosition=false,noticeTimer,generation=0,selection;
const fmt=v=>Number.isFinite(v)?String(Math.round(v)):'—';
const dist=v=>Number.isFinite(v)?v>=1000?(v/1000).toFixed(2)+' km':Math.round(v)+' m':'Entfernung unbekannt';
function notice(s){$('#notice').textContent=s;$('#notice').hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#notice').hidden=true,6000);}
function setMode(mode){prefs.mode=mode;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));save();if(data?.position&&mode!=='free')follow();}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));
function follow(){if(!data?.position)return;let p=L.latLng(data.position.lat,data.position.lon);if(prefs.mode==='preview'&&Number.isFinite(data.heading)){const pixel=map.project(p,map.getZoom()),r=data.heading*Math.PI/180;p=map.unproject(pixel.add([Math.sin(r)*130,-Math.cos(r)*130]),map.getZoom());}map.panTo(p,{animate:true,duration:.5});}
map.on('dragstart',()=>setMode('free'));map.on('zoomend',()=>{prefs.zoom=map.getZoom();save();});
map.getContainer().addEventListener('wheel',()=>setMode('free'),{passive:true});map.getContainer().addEventListener('touchstart',e=>{if(e.touches.length>1)setMode('free');},{passive:true});
$('#zoomIn').onclick=()=>{setMode('free');map.zoomIn();};$('#zoomOut').onclick=()=>{setMode('free');map.zoomOut();};$('#center').onclick=()=>{if(data?.position)setMode('follow');else notice('Keine aktuelle GPS-Position verfügbar.');};$('#north').onclick=()=>notice('Die Karte ist nach Norden ausgerichtet.');
$('#source').value=prefs.source;$('#source').onchange=e=>{prefs.source=e.target.value;generation++;data=null;seenPosition=false;stationsLayer.clearLayers();if(marker){map.removeLayer(marker);marker=null;}trace.setLatLngs([]);save();render({connected:false,updatedAt:0,events:[]});};
$('#display').onchange=e=>location.href='/?display='+e.target.value;
$('#full').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();map.invalidateSize();}catch{notice('Vollbild wird von diesem Browser nicht unterstützt.');}};
$('#infoButton').onclick=()=>$('#info').showModal();$('#closeCard').onclick=()=>{$('#card').hidden=true;selection=null;};
function card(e){selection=e.id;$('#card').hidden=false;$('#cardSource').textContent=e.source==='OSM'?'OPENSTREETMAP · REALE WELT':prefs.source==='demo'?'TSW-AUFNAHME · KEIN LIVE-STATUS':'TSW HTTP API · LIVE';$('#cardTitle').textContent=e.name;const parts=[];if(Number.isFinite(e.distance))parts.push('Voraus: '+dist(e.distance));if(Number.isFinite(e.speed))parts.push('Geschwindigkeit: '+fmt(e.speed)+' km/h');if(e.aspect)parts.push('Signalzustand: '+e.aspect);if(e.restriction)parts.push('Typ: '+e.restriction);if(e.source==='OSM')parts.push((e.reference?'Gespeicherte, geprüfte OSM-Referenz. ':'Realer Bahnhof. ')+'Zuordnung zur TSW-Strecke nicht bestätigt.');if(!e.position)parts.push('Die API liefert dafür keine bestätigte GPS-Position. Anzeige im Streckenband; kein erfundener Kartenpunkt.');$('#cardText').textContent=parts.join('\n');if(e.position){setMode('free');map.flyTo([e.position.lat,e.position.lon],Math.max(map.getZoom(),16),{duration:.7});}}
const routeStrip=new RouteStrip($('#band'),{onSelect:card,onResize:()=>map.invalidateSize()});
function render(incoming){const stale=!incoming.connected||Date.now()-incoming.updatedAt>5000;data=stale?{...incoming,position:null,speed:null,trackSpeed:null,permittedSpeed:null,lzbPermittedSpeed:null,lzbActive:null,pzbActive:null,events:[],trail:[],heading:null}:incoming;
 const demo=prefs.source==='demo';$('#status').textContent=demo?'AUFNAHME / DEMO':incoming.pending&&stale?'VERBINDUNG…':stale?'OFFLINE':data.position?'LIVE GPS':'LIVE · KEIN GPS';$('#status').className=stale?'offline':'';
 $('#vehicle').textContent=(data.vehicle||'Fahrzeug unbekannt').replace(/^RVM_CRG_DB_/,'').replace(/_C$/,'').replaceAll('_',' ');
 $('#speed').replaceChildren(document.createTextNode(fmt(data.speed)+' '));const unit=document.createElement('em');unit.textContent='km/h';$('#speed').append(unit);
 $('#trackSpeed').textContent=fmt(data.trackSpeed)+' km/h';$('#permitted').textContent=fmt(data.lzbActive&&Number.isFinite(data.lzbPermittedSpeed)?data.lzbPermittedSpeed:data.permittedSpeed)+' km/h';
 $('#protection').textContent=data.lzbActive===true?'LZB geführt':data.pzbActive===true?'PZB aktiv':data.lzbActive===false&&data.pzbActive===false?'Nicht aktiv':'Unbekannt';
 $('#place').textContent=data.place?data.place+' · TSW-Zielmarker':data.service?data.service+' · Streckenname unbekannt':'Streckenname nicht verfügbar';
 $('#mapHint').textContent=demo?'API-Aufnahme · reale Hintergrundkarte':'Reale Karte · kein vollständiges TSW-Gleisnetz';
 routeStrip.update(data,prefs.source+':'+(data.vehicleId||lastVehicle||''));if(selection){const current=data.events?.find(e=>e.id===selection);if(current)cardWithoutPan(current);else if(!selection.startsWith('osm-')){$('#card').hidden=true;selection=null;}}
 if(data.position){const p=[data.position.lat,data.position.lon];const icon=L.divIcon({className:'train-icon',iconSize:[34,34],iconAnchor:[17,17],html:Number.isFinite(data.heading)?`<svg class="train-arrow" viewBox="0 0 34 34" style="transform:rotate(${data.heading}deg)"><path d="M17 2L29 29L17 23L5 29Z" fill="#54e4ca" stroke="#edfefa" stroke-width="2"/></svg>`:'<div class="train-dot"></div>'});if(!marker)marker=L.marker(p,{icon,zIndexOffset:1000}).addTo(map).on('click',()=>card({id:'train',name:'Aktuelle Zugposition',source:'TSW',position:data.position}));else marker.setLatLng(p).setIcon(icon);trace.setLatLngs(data.trail||[]);$('#position').textContent=data.position.lat.toFixed(5)+'° N · '+data.position.lon.toFixed(5)+'° E · '+(Number.isFinite(data.heading)?Math.round(data.heading)+'° Bewegung':'Richtung noch unbekannt');if(!seenPosition||lastVehicle!==data.vehicleId){seenPosition=true;lastVehicle=data.vehicleId;map.setView(p,Math.max(map.getZoom(),14));}if(prefs.mode!=='free')follow();}
 else{if(marker){map.removeLayer(marker);marker=null;}trace.setLatLngs([]);$('#position').textContent='Keine aktuelle Zugposition';}
}
function cardWithoutPan(e){$('#cardText').textContent=[Number.isFinite(e.distance)?'Voraus: '+dist(e.distance):'',Number.isFinite(e.speed)?'Geschwindigkeit: '+fmt(e.speed)+' km/h':'',e.aspect?'Signalzustand: '+e.aspect:'',!e.position?'Keine bestätigte GPS-Position für dieses Ereignis.':''].filter(Boolean).join('\n');}
$('#stations').onclick=async()=>{if(prefs.source!=='live'||!data?.position){notice('OSM-Bahnhöfe benötigen eine aktuelle Live-Zugposition.');return;}$('#stations').disabled=true;$('#stations').textContent='Bahnhöfe werden geladen…';try{const r=await fetch('/api/navi/stations',{signal:AbortSignal.timeout(28000)});const payload=await r.json();if(!r.ok)throw Error(payload.message||'Nicht erreichbar');stationsLayer.clearLayers();for(const s of payload.stations){L.marker([s.position.lat,s.position.lon],{icon:L.divIcon({className:'station-icon',html:'▤',iconSize:[26,26],iconAnchor:[13,13]})}).addTo(stationsLayer).bindTooltip(Object.assign(document.createElement('span'),{textContent:s.name}),{direction:'top'}).on('click',()=>card(s));}notice(payload.stations.length+(payload.localReference?' gespeicherte OSM-Bahnhofsreferenz · kein vollständiges Verzeichnis.':' reale OSM-Bahnhöfe geladen · keine bestätigte TSW-Zuordnung.'));}catch(e){notice(e.message||'OSM-Abfrage fehlgeschlagen');}finally{$('#stations').disabled=false;$('#stations').textContent='Bahnhöfe aus OSM laden';}};
async function poll(){const g=generation;try{const demo=prefs.source==='demo';const r=await fetch(demo?'/navi-demo.json':'/api/navi',{cache:'no-store',signal:AbortSignal.timeout(4500)});if(!r.ok)throw Error();let incoming=await r.json();if(demo)incoming={...incoming,connected:true,recorded:true,updatedAt:Date.now()};if(g===generation)render(incoming);}catch{if(g===generation)render({connected:false,events:[],updatedAt:0});}setTimeout(poll,1000);}
setMode(prefs.mode);new ResizeObserver(()=>map.invalidateSize()).observe($('main'));poll();
